/* global document, Office, Word, localStorage */

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    const sideloadMsg = document.getElementById("sideload-msg");
    if (sideloadMsg) sideloadMsg.style.display = "none";

    const appBody = document.getElementById("app-body");
    if (appBody) appBody.style.display = "flex";

    // Inicializar gerenciador da API Key do Usuário
    initApiKeyManager();

    // Botão 0: Restaurar e Formatar via Gemini 2.5 Flash API
    const formatGeminiBtn = document.getElementById("format-gemini-btn");
    if (formatGeminiBtn) {
      formatGeminiBtn.onclick = restoreAndFormatWithGemini;
    }

    // Botão 1: Formatação Completa (Markdown + LaTeX)
    const formatBtn = document.getElementById("format-btn");
    if (formatBtn) {
      formatBtn.onclick = formatTextAutomatically;
    }

    // Botão 2: Formatação Exclusiva de LaTeX (Preserva layout Word existente)
    const formatLatexBtn = document.getElementById("format-latex-btn");
    if (formatLatexBtn) {
      formatLatexBtn.onclick = formatLatexOnly;
    }

    // Botão de compatibilidade #run
    const runBtn = document.getElementById("run");
    if (runBtn) {
      runBtn.onclick = formatTextAutomatically;
    }
  }
});

/**
 * Gerenciador de API Key inserida pelo usuário no aplicativo
 */
function initApiKeyManager() {
  const toggleBtn = document.getElementById("toggle-api-btn");
  const saveBtn = document.getElementById("save-api-key-btn");
  const inputContainer = document.getElementById("api-input-container");
  const keyInput = document.getElementById("gemini-api-key");
  const statusText = document.getElementById("api-status-text");

  const savedKey = getStoredApiKey();
  if (savedKey) {
    keyInput.value = savedKey;
    statusText.textContent = "✓ Chave salva e ativada";
    statusText.style.color = "#107c41";
    inputContainer.classList.add("hidden");
  } else {
    statusText.textContent = "⚠️ Nenhuma chave configurada";
    statusText.style.color = "#a80000";
    inputContainer.classList.remove("hidden");
  }

  if (toggleBtn) {
    toggleBtn.onclick = () => {
      inputContainer.classList.toggle("hidden");
    };
  }

  if (saveBtn) {
    saveBtn.onclick = () => {
      const key = keyInput.value.trim();
      if (key) {
        localStorage.setItem("gemini_api_key", key);
        statusText.textContent = "✓ Chave salva e ativada";
        statusText.style.color = "#107c41";
        inputContainer.classList.add("hidden");
        showStatus("API Key do Gemini salva com sucesso!", "success");
      } else {
        localStorage.removeItem("gemini_api_key");
        statusText.textContent = "⚠️ Nenhuma chave configurada";
        statusText.style.color = "#a80000";
        showStatus("Chave removida.", "warning");
      }
    };
  }
}

function getStoredApiKey() {
  return localStorage.getItem("gemini_api_key") || "";
}

/**
 * MODALIDADE RESTAURAÇÃO IA: Envia o texto para a API do Gemini 2.5 Flash,
 * restaura a sintaxe original (###, **, $...$, $$...$$) e formata no Word.
 */
export async function restoreAndFormatWithGemini() {
  const apiKey = getStoredApiKey();
  if (!apiKey) {
    showStatus("Insira sua API Key do Gemini no campo acima antes de usar a IA.", "warning");
    const inputContainer = document.getElementById("api-input-container");
    const keyInput = document.getElementById("gemini-api-key");
    if (inputContainer) inputContainer.classList.remove("hidden");
    if (keyInput) keyInput.focus();
    return;
  }

  setLoadingState(true, "format-gemini-btn", "btn-gemini-text", "btn-gemini-spinner", "Consultando Gemini AI...");

  try {
    await Word.run(async (context) => {
      const selection = context.document.getSelection();
      selection.load("text");
      await context.sync();

      let targetRange = selection;
      let rawText = selection.text;

      if (!rawText || rawText.trim().length === 0) {
        const body = context.document.body;
        body.load("text");
        await context.sync();

        targetRange = body;
        rawText = body.text;
      }

      if (!rawText || rawText.trim().length === 0) {
        showStatus("Nenhum texto encontrado no Word para restaurar.", "warning");
        setLoadingState(false, "format-gemini-btn", "btn-gemini-text", "btn-gemini-spinner", "Editor AI Gemini (Restaurar & Formatar)");
        return;
      }

      // 1. Chamar API do Gemini para reconstruir o Markdown e LaTeX
      const restoredMarkdown = await callGeminiApi(rawText, apiKey);

      // 2. Processar a resposta restaurada pelo nosso pipeline de conversão (Marked + KaTeX/OMML)
      const formattedHtml = processMarkdownAndLatex(restoredMarkdown);

      // 3. Injetar o HTML final no documento Word
      targetRange.insertHtml(formattedHtml, Word.InsertLocation.replace);
      await context.sync();

      showStatus("Texto restaurado pelo Gemini AI e formatado com sucesso!", "success");
    });
  } catch (error) {
    console.error("Erro ao processar com Gemini API:", error);
    showStatus("Erro na API do Gemini: " + (error.message || error), "error");
  } finally {
    setLoadingState(false, "format-gemini-btn", "btn-gemini-text", "btn-gemini-spinner", "Editor AI Gemini (Restaurar & Formatar)");
  }
}

/**
 * Requisita a API REST do Gemini (Google AI Studio) usando a chave fornecida pelo usuário
 */
async function callGeminiApi(rawText, apiKey) {
  const prompt = `Você é um assistente especialista em restauração de documentos científicos.
Sua missão: pegar o texto abaixo (que pode ter perdido marcações ao ser colado no Word a partir de celular/tablet) e REINSERIR 100% da sintaxe original:
1. Títulos com marcadores Markdown (#, ##, ###).
2. Listas e marcadores (ex: *, 1., 2.).
3. Negritos com **texto** e itálicos com *texto*.
4. Tabelas no formato Markdown (| Coluna | ... |).
5. Equações matemáticas: delimite fórmulas inline com $ ... $ e fórmulas em bloco centralizadas com $$ ... $$.

CRÍTICO: NÃO adicione introduções, explicações nem saudações (como 'Aqui está o seu texto'). Retorne EXATAMENTE E APENAS o texto com o Markdown e LaTeX restaurados.

Texto para restaurar:
${rawText}`;

  const models = ["gemini-2.5-flash", "gemini-1.5-flash"];
  let lastError = null;

  for (const model of models) {
    try {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [
            {
              parts: [{ text: prompt }]
            }
          ],
          generationConfig: {
            temperature: 0.1
          }
        })
      });

      if (!response.ok) {
        const errJson = await response.json().catch(() => ({}));
        throw new Error(errJson.error?.message || `HTTP ${response.status} no modelo ${model}`);
      }

      const data = await response.json();
      const textCandidate = data.candidates?.[0]?.content?.parts?.[0]?.text;
      if (textCandidate && textCandidate.trim().length > 0) {
        return textCandidate.trim();
      }
    } catch (err) {
      console.warn(`Tentativa com ${model} falhou:`, err);
      lastError = err;
    }
  }

  throw lastError || new Error("Não foi possível obter resposta da API do Gemini. Verifique se a sua chave de API é válida.");
}

function getKaTeX() {
  if (typeof window !== "undefined" && window.katex) return window.katex;
  if (typeof katex !== "undefined") return katex;
  return null;
}

function getMarked() {
  if (typeof window !== "undefined" && window.marked) return window.marked;
  if (typeof marked !== "undefined") return marked;
  return null;
}

/**
 * MODALIDADE 1: Formata Markdown Bruto + Equações LaTeX para HTML
 */
export async function formatTextAutomatically() {
  setLoadingState(true, "format-btn", "btn-text", "btn-spinner", "Formatando...");

  try {
    await Word.run(async (context) => {
      const selection = context.document.getSelection();
      selection.load("text");
      await context.sync();

      let targetRange = selection;
      let rawText = selection.text;

      if (!rawText || rawText.trim().length === 0) {
        const body = context.document.body;
        body.load("text");
        await context.sync();

        targetRange = body;
        rawText = body.text;
      }

      if (!rawText || rawText.trim().length === 0) {
        showStatus("Nenhum texto encontrado. Cole o texto no Word antes de formatar.", "warning");
        setLoadingState(false, "format-btn", "btn-text", "btn-spinner", "Formatar Texto da IA");
        return;
      }

      const formattedHtml = processMarkdownAndLatex(rawText);
      targetRange.insertHtml(formattedHtml, Word.InsertLocation.replace);
      await context.sync();

      showStatus("Texto e equações nativas formatados com sucesso!", "success");
    });
  } catch (error) {
    console.error("Erro ao formatar texto:", error);
    showStatus("Erro ao processar formatação: " + (error.message || error), "error");
  } finally {
    setLoadingState(false, "format-btn", "btn-text", "btn-spinner", "Formatar Texto da IA");
  }
}

/**
 * MODALIDADE 2: Formata APENAS o LaTeX presente no documento
 */
export async function formatLatexOnly() {
  setLoadingState(true, "format-latex-btn", "btn-latex-text", "btn-latex-spinner", "Formatando LaTeX...");

  try {
    await Word.run(async (context) => {
      const selection = context.document.getSelection();
      selection.load("text");
      const selectionHtml = selection.getHtml();
      await context.sync();

      let targetRange = selection;
      let rawText = selection.text;
      let htmlContent = selectionHtml ? selectionHtml.value : "";

      if (!rawText || rawText.trim().length === 0) {
        const body = context.document.body;
        body.load("text");
        const bodyHtml = body.getHtml();
        await context.sync();

        targetRange = body;
        rawText = body.text;
        htmlContent = bodyHtml ? bodyHtml.value : "";
      }

      if (!rawText || rawText.trim().length === 0) {
        showStatus("Nenhum texto encontrado. Cole o texto no Word antes de formatar.", "warning");
        setLoadingState(false, "format-latex-btn", "btn-latex-text", "btn-latex-spinner", "Formatar LaTeX");
        return;
      }

      let finalHtml = "";
      if (htmlContent && htmlContent.trim().length > 0) {
        const cleanBody = extractCleanBodyHtml(htmlContent);
        finalHtml = replaceLatexInHtml(cleanBody);
      } else {
        finalHtml = replaceLatexInText(rawText);
      }

      targetRange.insertHtml(finalHtml, Word.InsertLocation.replace);
      await context.sync();

      showStatus("Equações LaTeX convertidas para equações nativas do Word!", "success");
    });
  } catch (error) {
    console.error("Erro ao formatar apenas LaTeX:", error);
    showStatus("Erro ao converter LaTeX: " + (error.message || error), "error");
  } finally {
    setLoadingState(false, "format-latex-btn", "btn-latex-text", "btn-latex-spinner", "Formatar LaTeX");
  }
}

function extractCleanBodyHtml(fullHtml) {
  if (!fullHtml) return "";

  const bodyMatch = fullHtml.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  let html = bodyMatch ? bodyMatch[1] : fullHtml;

  html = html.replace(/^[\s\n]*<div[^>]*class=["']?WordSection1["']?[^>]*>([\s\S]*)<\/div>[\s\n]*$/i, "$1");
  html = html.replace(/^[\s\n]*<table[^>]*>[\s\n]*<tr[^>]*>[\s\n]*<td[^>]*>([\s\S]*)<\/td>[\s\n]*<\/tr>[\s\n]*<\/table>[\s\n]*$/i, "$1");

  return html.trim();
}

function replaceLatexInHtml(htmlContent) {
  const parts = htmlContent.split(/(<[^>]+>)/g);

  for (let i = 0; i < parts.length; i++) {
    if (parts[i] && !parts[i].startsWith("<")) {
      parts[i] = processLatexTextSegment(parts[i]);
    }
  }

  return parts.join("");
}

function processLatexTextSegment(text) {
  if (!text || !text.trim()) return text;

  let processed = text;

  processed = processed.replace(/\$\$\s*([\s\S]*?)\s*\$\$/g, (match, latexCode) => {
    return latexToOMMLAndFallback(latexCode, true);
  });

  processed = processed.replace(/\\\[\s*([\s\S]*?)\s*\\\]/g, (match, latexCode) => {
    return latexToOMMLAndFallback(latexCode, true);
  });

  processed = processed.replace(/(?<!\$)\$([^\$\n]+?)\$(?!\$)/g, (match, latexCode) => {
    return latexToOMMLAndFallback(latexCode, false);
  });

  processed = processed.replace(/\\\(\s*([\s\S]*?)\s*\\\)/g, (match, latexCode) => {
    return latexToOMMLAndFallback(latexCode, false);
  });

  const rawLatexRegex = /(?:(?:\d+[\s,.]*)?\\[a-zA-Z]+(?:\{[^{}]*\}|_[a-zA-Z0-9{}]+|\^[a-zA-Z0-9{}]+|[\s\w=+\-*\/(),.{}]*)*)/g;

  const mathSplit = processed.split(/(<p style="text-align: center[\s\S]*?<\/p>|<span class="word-math-inline"[\s\S]*?<\/span>|<math[\s\S]*?<\/math>)/gi);
  for (let j = 0; j < mathSplit.length; j++) {
    if (mathSplit[j] && !mathSplit[j].toLowerCase().startsWith("<p style=\"text-align: center") && !mathSplit[j].toLowerCase().startsWith("<span class=\"word-math-inline") && !mathSplit[j].toLowerCase().startsWith("<math")) {
      mathSplit[j] = mathSplit[j].replace(rawLatexRegex, (rawMatch) => {
        if (/\\[a-zA-Z]+/.test(rawMatch)) {
          return latexToOMMLAndFallback(rawMatch, false);
        }
        return rawMatch;
      });
    }
  }

  return mathSplit.join("");
}

function latexToOMMLAndFallback(latexCode, isBlock) {
  const cleanCode = decodeHtmlEntities(latexCode).trim();
  let ommlXml = "";
  let cleanMathML = "";

  const kt = getKaTeX();
  if (kt && typeof kt.renderToString === "function") {
    try {
      const rawKatex = kt.renderToString(cleanCode, {
        displayMode: isBlock,
        output: "mathml",
        throwOnError: false,
      });
      cleanMathML = cleanMathMLForWord(rawKatex, isBlock);
      ommlXml = mathmlToOMML(cleanMathML);
    } catch (err) {
      console.warn("Erro ao converter LaTeX para MathML/OMML:", err);
    }
  }

  const readableMath = formatReadableMath(cleanCode);

  if (isBlock) {
    return `<p style="text-align: center; margin: 10pt 0; line-height: 1.3;">` +
             (ommlXml ? `<m:oMathPara xmlns:m="http://schemas.microsoft.com/office/2004/12/omml"><m:oMath>${ommlXml}</m:oMath></m:oMathPara>` : "") +
             cleanMathML +
             `<span class="word-math-fallback" style="font-family: 'Cambria Math', 'Segoe UI Symbol', 'STIX Two Math', serif; font-size: 11pt; font-style: italic; color: #000000;">${readableMath}</span>` +
           `</p>`;
  } else {
    return `<span class="word-math-inline" style="font-family: 'Cambria Math', 'Segoe UI Symbol', 'STIX Two Math', serif; font-size: 11pt; font-style: italic; color: #000000;">` +
             (ommlXml ? `<m:oMath xmlns:m="http://schemas.microsoft.com/office/2004/12/omml">${ommlXml}</m:oMath>` : "") +
             cleanMathML +
             `${readableMath}` +
           `</span>`;
  }
}

function mathmlToOMML(mathmlStr) {
  if (!mathmlStr) return "";

  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(mathmlStr, "text/xml");
    const mathNode = doc.querySelector("math");
    if (!mathNode) return "";

    return convertNodeToOMML(mathNode);
  } catch (e) {
    return "";
  }
}

function convertNodeToOMML(node) {
  if (!node) return "";
  let result = "";

  for (let i = 0; i < node.childNodes.length; i++) {
    const child = node.childNodes[i];
    if (child.nodeType === 3) {
      const txt = child.nodeValue.trim();
      if (txt) {
        result += `<m:r><m:t>${escapeXml(txt)}</m:t></m:r>`;
      }
      continue;
    }

    if (child.nodeType !== 1) continue;

    const tag = child.tagName.toLowerCase();

    if (tag === "mfrac") {
      const children = getElementChildNodes(child);
      const num = children[0] ? convertNodeToOMML(children[0]) : "";
      const den = children[1] ? convertNodeToOMML(children[1]) : "";
      result += `<m:f><m:num>${num}</m:num><m:den>${den}</m:den></m:f>`;
    } else if (tag === "msub") {
      const children = getElementChildNodes(child);
      const base = children[0] ? convertNodeToOMML(children[0]) : "";
      const sub = children[1] ? convertNodeToOMML(children[1]) : "";
      result += `<m:sSub><m:e>${base}</m:e><m:sub>${sub}</m:sub></m:sSub>`;
    } else if (tag === "msup") {
      const children = getElementChildNodes(child);
      const base = children[0] ? convertNodeToOMML(children[0]) : "";
      const sup = children[1] ? convertNodeToOMML(children[1]) : "";
      result += `<m:sSup><m:e>${base}</m:e><m:sup>${sup}</m:sup></m:sSup>`;
    } else if (tag === "msubsup") {
      const children = getElementChildNodes(child);
      const base = children[0] ? convertNodeToOMML(children[0]) : "";
      const sub = children[1] ? convertNodeToOMML(children[1]) : "";
      const sup = children[2] ? convertNodeToOMML(children[2]) : "";
      result += `<m:sSubSup><m:e>${base}</m:e><m:sub>${sub}</m:sub><m:sup>${sup}</m:sup></m:sSubSup>`;
    } else if (tag === "msqrt") {
      const expr = convertNodeToOMML(child);
      result += `<m:rad><m:deg/><m:e>${expr}</m:e></m:rad>`;
    } else if (tag === "mi" || tag === "mn" || tag === "mo" || tag === "mtext") {
      const txt = child.textContent.trim();
      if (txt) {
        result += `<m:r><m:t>${escapeXml(txt)}</m:t></m:r>`;
      }
    } else {
      result += convertNodeToOMML(child);
    }
  }

  return result;
}

function getElementChildNodes(node) {
  const list = [];
  for (let i = 0; i < node.childNodes.length; i++) {
    if (node.childNodes[i].nodeType === 1) {
      list.push(node.childNodes[i]);
    }
  }
  return list;
}

function formatReadableMath(latex) {
  if (!latex) return "";
  let txt = latex;

  txt = txt.replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g, "($1) / ($2)");
  txt = txt.replace(/\\text\{([^{}]+)\}/g, "$1");
  txt = txt.replace(/\\mu/g, "μ");
  txt = txt.replace(/\\alpha/g, "α");
  txt = txt.replace(/\\beta/g, "β");
  txt = txt.replace(/\\gamma/g, "γ");
  txt = txt.replace(/\\delta/g, "δ");
  txt = txt.replace(/\\theta/g, "θ");
  txt = txt.replace(/\\pi/g, "π");
  txt = txt.replace(/\\cdot/g, " · ");
  txt = txt.replace(/\\implies/g, " ⇒ ");
  txt = txt.replace(/\\times/g, " × ");
  txt = txt.replace(/\\div/g, " ÷ ");
  txt = txt.replace(/\\le/g, " ≤ ");
  txt = txt.replace(/\\ge/g, " ≥ ");
  txt = txt.replace(/\\neq/g, " ≠ ");
  txt = txt.replace(/\\approx/g, " ≈ ");
  txt = txt.replace(/\\infty/g, " ∞ ");
  txt = txt.replace(/\\sqrt\{([^{}]+)\}/g, "√($1)");

  txt = txt.replace(/_\{([^{}]+)\}/g, "_$1");
  txt = txt.replace(/\^\{([^{}]+)\}/g, "^$1");

  return escapeHtml(txt);
}

function replaceLatexInText(rawText) {
  let html = escapeHtml(rawText);
  html = html.replace(/\n/g, "<br>");
  return processLatexTextSegment(html);
}

function processMarkdownAndLatex(text) {
  const mathStore = [];
  const mk = getMarked();

  if (mk && mk.setOptions) {
    mk.setOptions({
      gfm: true,
      breaks: true,
    });
  }

  let processedText = text.replace(/\$\$\s*([\s\S]*?)\s*\$\$/g, (match, latexCode) => {
    const id = mathStore.length;
    const token = `XMATHBLOCKTOKEN${id}X`;
    const mathHtml = latexToOMMLAndFallback(latexCode, true);
    mathStore.push({
      token: token,
      html: mathHtml,
      isBlock: true,
    });
    return token;
  });

  processedText = processedText.replace(/(?<!\$)\$([^\$\n]+?)\$(?!\$)/g, (match, latexCode) => {
    const id = mathStore.length;
    const token = `XMATHINLINETOKEN${id}X`;
    const mathHtml = latexToOMMLAndFallback(latexCode, false);
    mathStore.push({
      token: token,
      html: mathHtml,
      isBlock: false,
    });
    return token;
  });

  let htmlOutput = "";
  if (mk) {
    htmlOutput = typeof mk.parse === "function" ? mk.parse(processedText) : mk(processedText);
  } else {
    htmlOutput = simpleMarkdownFallback(processedText);
  }

  htmlOutput = htmlOutput.replace(/<h3>/gi, '<h3 style="color: #0f6cbd; font-family: \'Segoe UI\', sans-serif; margin-top: 14pt; margin-bottom: 6pt;">');
  htmlOutput = htmlOutput.replace(/<hr\s*\/?>/gi, '<hr style="border: none; border-top: 1px solid #d1d1d1; margin: 14pt 0;" />');

  mathStore.forEach((item) => {
    if (item.isBlock) {
      const pPattern = new RegExp(`<p>\\s*${item.token}\\s*<\\/p>`, "g");
      if (pPattern.test(htmlOutput)) {
        htmlOutput = htmlOutput.replace(pPattern, item.html);
      } else {
        htmlOutput = htmlOutput.replace(new RegExp(item.token, "g"), item.html);
      }
    } else {
      htmlOutput = htmlOutput.replace(new RegExp(item.token, "g"), item.html);
    }
  });

  return htmlOutput;
}

function renderLatexToMathML(latex, isBlock) {
  const kt = getKaTeX();
  if (kt && typeof kt.renderToString === "function") {
    try {
      const rawKatex = kt.renderToString(latex.trim(), {
        displayMode: isBlock,
        output: "mathml",
        throwOnError: false,
      });
      return cleanMathMLForWord(rawKatex, isBlock);
    } catch (err) {
      console.warn("Erro ao renderizar LaTeX via KaTeX:", err);
    }
  }
  return `<span style="font-family: 'Cambria Math', serif; font-style: italic;">${escapeHtml(latex)}</span>`;
}

function cleanMathMLForWord(rawMathML, isBlock) {
  if (!rawMathML) return "";

  const match = rawMathML.match(/<math[\s\S]*?<\/math>/i);
  let xml = match ? match[0] : rawMathML;

  xml = xml.replace(/<annotation[\s\S]*?<\/annotation>/gi, "");
  xml = xml.replace(/<semantics[\s\S]*?>([\s\S]*?)<\/semantics>/gi, "$1");

  if (!/xmlns=/i.test(xml)) {
    xml = xml.replace(/<math/i, '<math xmlns="http://www.w3.org/1998/Math/MathML"');
  }

  if (isBlock && !/display=/i.test(xml)) {
    xml = xml.replace(/<math/i, '<math display="block"');
  }

  return xml;
}

function decodeHtmlEntities(str) {
  if (!str) return "";
  return str
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ");
}

function escapeXml(str) {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function setLoadingState(isLoading, btnId, textId, spinnerId, loadingText) {
  const btn = document.getElementById(btnId);
  const btnText = document.getElementById(textId);
  const btnSpinner = document.getElementById(spinnerId);

  if (!btn || !btnText || !btnSpinner) return;

  if (isLoading) {
    btn.disabled = true;
    btnText.textContent = loadingText;
    btnSpinner.classList.remove("hidden");
  } else {
    btn.disabled = false;
    if (btnId === "format-gemini-btn") btnText.textContent = "Editor AI Gemini (Restaurar & Formatar)";
    else if (btnId === "format-btn") btnText.textContent = "Formatar Texto da IA";
    else if (btnId === "format-latex-btn") btnText.textContent = "Formatar LaTeX";
    btnSpinner.classList.add("hidden");
  }
}

function showStatus(message, type) {
  const banner = document.getElementById("status-banner");
  const messageEl = document.getElementById("status-message");
  const iconEl = document.getElementById("status-icon");

  if (!banner || !messageEl || !iconEl) return;

  banner.className = `status-banner ${type}`;
  messageEl.textContent = message;

  if (type === "success") {
    iconEl.innerHTML = "✓";
  } else if (type === "warning") {
    iconEl.innerHTML = "⚠️";
  } else if (type === "error") {
    iconEl.innerHTML = "✕";
  }

  banner.classList.remove("hidden");

  if (type === "success") {
    setTimeout(() => {
      banner.classList.add("hidden");
    }, 5000);
  }
}

function escapeHtml(str) {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function simpleMarkdownFallback(src) {
  let html = src;
  html = html.replace(/^### (.*$)/gim, "<h3>$1</h3>");
  html = html.replace(/^## (.*$)/gim, "<h2>$1</h2>");
  html = html.replace(/^# (.*$)/gim, "<h1>$1</h1>");
  html = html.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
  html = html.replace(/\*(.*?)\*/g, "<em>$1</em>");
  return html.split("\n\n").map((p) => `<p>${p}</p>`).join("");
}
